var all=UnityEditor.AssetDatabase.GetAllAssetPaths().Where(p=>p.StartsWith("Assets/")&&!UnityEditor.AssetDatabase.IsValidFolder(p)).ToArray();
var roots=new System.Collections.Generic.HashSet<string>(UnityEditor.EditorBuildSettings.scenes.Where(s=>s.enabled).Select(s=>s.path));
foreach(var path in all){var extension=System.IO.Path.GetExtension(path).ToLowerInvariant();if(path.Contains("/Resources/")||path.StartsWith("Assets/StreamingAssets/")||new[]{".cs",".asmdef",".asmref",".dll",".shader",".shadergraph",".shadersubgraph",".hlsl",".cginc",".compute"}.Contains(extension))roots.Add(path);}
foreach(var path in System.IO.Directory.GetFiles("ProjectSettings","*.asset"))foreach(System.Text.RegularExpressions.Match match in System.Text.RegularExpressions.Regex.Matches(System.IO.File.ReadAllText(path),@"guid:\s*([a-f0-9]{32})")){var asset=UnityEditor.AssetDatabase.GUIDToAssetPath(match.Groups[1].Value);if(!string.IsNullOrEmpty(asset))roots.Add(asset);}
var referenced=new System.Collections.Generic.HashSet<string>(UnityEditor.AssetDatabase.GetDependencies(roots.ToArray(),true));
var protectedFolders=new[]{"Assets/Oculus/","Assets/InteractionSDK/","Assets/Plugins/","Assets/XR/","Assets/TextMesh Pro/","Assets/CompositionLayers/"};
var extensions=new[]{".prefab",".fbx",".obj",".blend",".mat",".png",".jpg",".jpeg",".tga",".psd",".exr",".hdr",".wav",".mp3",".ogg",".anim",".controller",".overridecontroller",".unity",".asset"};
var candidates=all.Where(p=>!referenced.Contains(p)&&!protectedFolders.Any(f=>p.StartsWith(f))&&extensions.Contains(System.IO.Path.GetExtension(p).ToLowerInvariant())).Select(p=>new{path=p,bytes=new System.IO.FileInfo(p).Length,category=p.Contains("/Demo")||p.Contains("/Samples/")||p.Contains("/_Recovery/")||p.Contains("/TutorialInfo/")?"Demos, ejemplos o recuperación":"Sin referencia estática detectada",folder=p.Split('/').Length>2?p.Split('/')[1]:"Assets"}).OrderByDescending(x=>x.bytes).ToArray();
var summary=candidates.GroupBy(x=>x.folder).Select(g=>new{folder=g.Key,count=g.Count(),bytes=g.Sum(x=>x.bytes)}).OrderByDescending(g=>g.bytes).ToArray();
var report=new{scope="Enabled build scenes, Resources, StreamingAssets, project settings references and all scripts/shaders protected",warning="Candidates for manual review, not safe-to-delete proof. Dynamic string loads and external tools may still reference them. Nothing deleted.",rootCount=roots.Count,referencedAssets=referenced.Count,candidateCount=candidates.Length,candidateSourceMiB=System.Math.Round(candidates.Sum(x=>x.bytes)/1048576.0,2),folders=summary,assets=candidates};
System.IO.File.WriteAllText("Docs/UnusedAssetsReview.json",Newtonsoft.Json.JsonConvert.SerializeObject(report,Newtonsoft.Json.Formatting.Indented));
var markdown=new System.Text.StringBuilder("# Assets para revisar\n\nNo se eliminó ningún archivo. Esta lista detecta ausencia de referencias estáticas, no demuestra que un asset se pueda borrar. Las cargas por rutas de texto, herramientas de Editor y escenas fuera del build necesitan revisión manual.\n\nSe protegieron escenas habilitadas, Resources, StreamingAssets, referencias de ProjectSettings, scripts y shaders, además de carpetas de integración Meta/XR/Plugins/TMP.\n\n");
markdown.AppendLine("Candidatos: **"+candidates.Length+"**. Tamaño de archivos fuente: **"+report.candidateSourceMiB+" MiB**, no memoria de ejecución ni ahorro garantizado del build.\n");
markdown.AppendLine("## Resumen por carpeta\n\n| Carpeta | Assets | MiB fuente |\n|---|---:|---:|");
foreach(var group in summary)markdown.AppendLine("| "+group.folder+" | "+group.count+" | "+System.Math.Round(group.bytes/1048576.0,2)+" |");
markdown.AppendLine("\n## Los 200 archivos de mayor tamaño\n\nListado completo, con rutas, en UnusedAssetsReview.json.\n\n| Asset | MiB | Clasificación |\n|---|---:|---|");
foreach(var asset in candidates.Take(200)){var absolute=System.IO.Path.GetFullPath(asset.path).Replace('\\','/');markdown.AppendLine("| ["+asset.path+"](<"+absolute+">) | "+System.Math.Round(asset.bytes/1048576.0,2)+" | "+asset.category+" |");}
System.IO.File.WriteAllText("Docs/UnusedAssetsReview.md",markdown.ToString());
return new{candidates=report.candidateCount,sourceMiB=report.candidateSourceMiB,largestFolders=summary.Take(8).ToArray(),report="Docs/UnusedAssetsReview.md",deleted=0};
